sys_variable_value.value:
(function execute(inputs, outputs) {
    var dt_reqArray = [];
    var enc_qry = 'traveller='+inputs.traveller_sysid;
    var dt_req = new GlideRecord('x_snc_duty_travel_duty_travel_req');
    dt_req.addEncodedQuery(enc_qry);
    dt_req.query();
    while (dt_req.next()) {
        dt_reqArray.push({
            leaving_from: dt_req.getDisplayValue('leaving_from'),
            going_to: dt_req.getDisplayValue('going_to'),
            cabin_class: dt_req.getDisplayValue('cabin_class'),
            trip_type: dt_req.getDisplayValue('trip_type'),
            request_date: dt_req.getDisplayValue('opened_at').split(' ')[0]
        });
    }
    outputs.dt_json = JSON.stringify(dt_reqArray);
    outputs.dt_count = dt_reqArray.length;

})(inputs, outputs);

